use vstd::prelude::*;
verus! {

// The spec function classifying the sign of each i8 value.
spec fn classify_sign(value: i8) -> i8 {
    if value < 0 {
        -1
    } else if value == 0 {
        0
    } else {
        1
    }
}

fn sign(x: Vec<i8>) -> (result: Vec<i8>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        forall|i: usize| (i < x.len()) ==> (result[i] == classify_sign(x[i]))
{
    let mut result = Vec::<i8>::with_capacity(x.len());
    let mut idx: usize = 0;

    // Iterate over each element of the input vector
    while idx < x.len()
        invariant
            idx <= x.len(),
            result.len() == idx,
            forall(|j: usize| (j < idx) ==> (result[j] == classify_sign(x[j]))),
        decreases x.len() - idx,
    {
        let val: i8 = x[idx];
        let classified: i8;
        if val < 0 {
            classified = -1;
        } else if val == 0 {
            classified = 0;
        } else {
            classified = 1;
        }
        result.push(classified);
        idx += 1;
    }

    result
}

}
